{
  "findings": [
    {
      "check_id": "CKV_AZURE_112",
      "title": "Ensure that key vault key is backed by HSM",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The key is generated using software protection (default) instead of Hardware Security Module (HSM). For production environments, especially for keys used in encryption/signing, HSM-backed keys provide stronger security guarantees against extraction."
    },
    {
      "check_id": "CKV_AZURE_40",
      "title": "Ensure that the expiration date is set on all keys",
      "resource": "azurerm_key_vault_key.generated",
      "severity": "MEDIUM",
      "explanation": "The `expiration_date` attribute is not set. Without an expiration date, the key remains valid indefinitely, which violates best practices for key lifecycle management and increases the risk window if the key is compromised."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_key\" \"generated\" {\n  name         = \"terragoat-generated-certificate-${var.environment}\"\n  key_vault_id = azurerm_key_vault.example.id\n  key_type     = \"RSA\"\n  key_size     = 2048\n  key_opts = [\n    \"decrypt\",\n    \"encrypt\",\n    \"sign\",\n    \"unwrapKey\",\n    \"verify\",\n    \"wrapKey\",\n  ]\n  hsm_type       = \"HSM\"\n  expiration_date = timeadd(timestamp(), \"8760h\") # Expires in 1 year\n}",
  "fix_summary": "Added `hsm_type = \"HSM\"` to ensure the key is backed by a Hardware Security Module as per CKV_AZURE_112. Added `expiration_date` using `timeadd` to set a one-year validity period, addressing CKV_AZURE_40 regarding missing expiration dates."
}
